  say(`[${label}] obj=${orUnavailable(rec.objectiveId)} common=${JSON.stringify(rec.common)} pose=${JSON.stringify(rec.bodyPose)} supported=${orUnavailable(rec.supported)}`);
  const png = await page.screenshot().catch(() => null);
