  if (!gate('pointer-lock-and-focus', ctl.pointerLockIsCanvas === true && ctl.hasFocus === true, { pointerLockIsCanvas: ctl.pointerLockIsCanvas, hasFocus: ctl.hasFocus, attempts: lockAttempts }))
