    const atUp = await cgSnap(page);
    await sleep(200);
    const a = await cgSnap(page);
    const rc = keyReceipt({ from: poseOf(b), to: poseOf(a), up: b?.up ?? [0, 1, 0] });
    const pUp = poseOf(atUp); const pEnd = poseOf(a);
