// --- earned Origin entry gate ------------------------------------------------
/** The signed Origin body id. A landing anywhere else is not the Origin landing. */
export const SIGNED_ORIGIN_PLANET_ID = '-1,-1';
/** The signed chapter anchor that names the Origin landing itself. */
export const ORIGIN_LANDED_ANCHOR_ID = 'anc.cg.origin-landed';

/**
 * PREREQUISITE F GATE. Everything downstream (drawing, save, Continue, new
 * action) is refused unless the return flight ACTUALLY landed: the shipped
 * milestone latched, the live active planet is EXACTLY the signed Origin body,
 * the named Origin-landing anchor appears in BOTH the signed-AV named
 * activation history AND the chapter's own fired-anchor history, the body is
 * grounded and on foot controls, and the renderer is really producing frames.
 *
 * TIGHTENED FOR THE ARRIVAL LANE (producer-earned-continue-prep-review.json,
 * requiredBeforeRuntime 1 and 2). The previous version accepted:
 *   - ANY activePlanetId that merely DIFFERED from the departure body, which
 *     proves only that a world handoff happened, not that it was the Origin; and
 *   - ANY NON-EMPTY named AV history, which a lift-only history satisfies
 *     without the landing ever occurring.
 * Both are now refused. Raw observations (the full named history, the fired
 * chapter anchors, the raw key count, sequence numbers) are still reported
 * verbatim so a refusal is diagnosable; nothing measured is discarded.
 *
 * `minFps` remains an OPERATIONAL probe threshold (the run was not rendering),
 * not a performance acceptance and not a claim about rendering below 15 fps.
 */
export function earnedOriginGate({
  originLandedMilestone = false,
  bootActivePlanetId = null, landedActivePlanetId = null,
  locationMode = null, controlMode = null,
  supported = null, bodyPose = null,
  fps = null, minFps = 15,
  av = null, requireNamedAnchors = true,
  anchors = null,
  requireOriginPlanetId = SIGNED_ORIGIN_PLANET_ID,
  requireOriginLandedAnchor = ORIGIN_LANDED_ANCHOR_ID
} = {}) {
  const problems = [];
  if (originLandedMilestone !== true) problems.push('story:ch13-origin-landed never latched: the return flight did not physically land');
  if (!landedActivePlanetId) problems.push('no live activePlanetId was read at the landing: the active origin is UNMEASURED');
  else if (bootActivePlanetId && landedActivePlanetId === bootActivePlanetId) {
    problems.push(`activePlanetId is still the departure body ${bootActivePlanetId}: no world handoff was measured`);
  }
  // EXACT signed Origin id, not merely "different from departure".
  if (requireOriginPlanetId != null && landedActivePlanetId != null
    && landedActivePlanetId !== requireOriginPlanetId) {
    problems.push(`landed activePlanetId ${JSON.stringify(landedActivePlanetId)} is not the signed Origin ${JSON.stringify(requireOriginPlanetId)}: a different body is not the Origin landing`);
  }

